import { MODULE_ID } from "./constants.js";
// </auto-imports>
// Foundry-native world-permission gate — extracted from mobile-bridge.js.

// --- Foundry-native world-permission gate (Trello #6) ---
//
// The GM already configures who may do these on Foundry's own "Configure
// Permissions" screen (CONST.USER_PERMISSIONS, per-world, GM-editable). The
// bridge adds no permission UI of its own: it just enforces the same rule
// Foundry itself would enforce in the browser, via `user.can(<permission>)`.
//
// Only actions with a genuine CONST.USER_PERMISSIONS analog are listed here.
// Actions that are owner-based with no native world-permission (editing your
// own sheet, toggling your own token's conditions, moving your own token,
// requesting items, homebrew content creation, etc.) are deliberately absent
// — those were opened up to all players on purpose and this gate must not
// re-lock them. A few actions already had their own inline `user.can(...)`
// check before this gate existed (scene.drawing.create/delete via
// DRAWING_CREATE, scene.door.toggle via WALL_DOORS) and are left as-is rather
// than folded in here, since their response shape (`{error:"not_allowed"}`
// inside an ok:true result) is already relied on by the app.
//
// `actor.portrait.set` / `actor.tokenImage.set` are also deliberately absent:
// they upload art for your OWN character, and `uploadActorImage` is called
// with `requirePermission: false` there on purpose (see its call sites) so a
// brand-new player can set a portrait before any GM has granted them
// anything. Gating them here would re-lock that.
export const PERMISSION_GATED_ACTIONS = new Map([
  // Area-effect templates placed from a spell/item that targets an area.
  ["template.place", "TEMPLATE_CREATE"],
  ["template.rotate", "TEMPLATE_CREATE"],
  // Repositioning an aimed template to a tapped cell is the same canvas right.
  ["template.moveToCell", "TEMPLATE_CREATE"],
  // Long-press "ping the map" broadcast to the rest of the table.
  ["scene.ping", "PING_CANVAS"],
  // Always an image upload (imageBase64 is required), unlike createLoot/
  // updateLoot where the image is optional and already gated per-field by
  // `uploadActorImage`'s own `requirePermission` check.
  ["actor.item.setImage", "FILES_UPLOAD"],
  // A player's private notebook entry is still a real JournalEntry document,
  // which Foundry itself gates by JOURNAL_CREATE — not NOTE_CREATE, which
  // controls canvas map-pins (this bridge has no map-pin action).
  ["journal.note.create", "JOURNAL_CREATE"],
  // New character creation. Foundry's own default already withholds this from
  // plain Players in a fresh world; a GM running player-driven character
  // creation grants it the same way they would for the browser sheet.
  ["actor.create", "ACTOR_CREATE"]
]);

export const PERMISSION_IDS_REPORTED = [...new Set(PERMISSION_GATED_ACTIONS.values())];
export const permissionGateWarned = new Set();

/**
 * Whether `permission` exists on the installed core's own CONST.USER_PERMISSIONS.
 * Read live rather than hardcoded, because the exact set can drift between
 * v12/v13/v14 — a name this module got wrong (or that a future core removes)
 * fails OPEN (logged once) instead of inventing a lock that was never real.
 */
export function permissionExistsOnCore(permission) {
  return !!(CONST?.USER_PERMISSIONS &&
    Object.prototype.hasOwnProperty.call(CONST.USER_PERMISSIONS, permission));
}

export function warnUnknownPermissionOnce(permission, action) {
  if (permissionGateWarned.has(permission)) return;
  permissionGateWarned.add(permission);
  console.warn(
    `[${MODULE_ID}] CONST.USER_PERMISSIONS has no "${permission}" on this Foundry ` +
    `version (checked for action "${action}") — leaving it ungated rather than guessing`
  );
}

/** `user.can`/`user.hasPermission`, whichever this core exposes; fails closed on error. */
export function foundryUserCan(user, permission) {
  try {
    if (typeof user?.can === "function") return !!user.can(permission);
    if (typeof user?.hasPermission === "function") return !!user.hasPermission(permission);
  } catch (err) {
    console.warn(`[${MODULE_ID}] permission check failed for ${permission}`, err);
  }
  return false;
}

/**
 * `{ <PERMISSION>: boolean }` for the permissions the mobile app gates UI on,
 * computed live via `user.can(...)`. A permission missing from this core's
 * CONST.USER_PERMISSIONS reports `true` (nothing to enforce, so the app should
 * not hide the control either) rather than a guessed default.
 */
export function computeMobilePermissions(user) {
  const permissions = {};
  for (const id of PERMISSION_IDS_REPORTED) {
    permissions[id] = permissionExistsOnCore(id) ? foundryUserCan(user, id) : true;
  }
  return permissions;
}
